"use strict";
(() => {
const STORAGE_KEY = "moya-vahta.prototype.v1";
const $ = id => document.getElementById(id);
const icon = (id, extra="") => `<svg class="${extra}" aria-hidden="true"><use href="#i-${id}"></use></svg>`;
const html = value => String(value ?? "").replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id = () => (globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`);
const localISO = date => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const parseISO = iso => {const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso||""));return m?new Date(+m[1],+m[2]-1,+m[3],12):new Date()};
const today = () => localISO(new Date());
const shiftDate = (iso, days) => {const d=parseISO(iso);d.setDate(d.getDate()+days);return localISO(d)};
const daysBetween = (a,b) => Math.round((Date.UTC(parseISO(b).getFullYear(),parseISO(b).getMonth(),parseISO(b).getDate())-Date.UTC(parseISO(a).getFullYear(),parseISO(a).getMonth(),parseISO(a).getDate()))/86400000);
const monthKey = iso => iso.slice(0,7);
const currentMonth = () => today().slice(0,7);
const addMonth = (key,diff) => {const [y,m]=key.split('-').map(Number);const d=new Date(y,m-1+diff,1,12);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`};
const longMonth = key => {const [y,m]=key.split('-').map(Number);const s=new Date(y,m-1,1).toLocaleDateString('ru-RU',{month:'long',year:'numeric'});return s.charAt(0).toUpperCase()+s.slice(1)};
const dateFull = iso => parseISO(iso).toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'});
const dateShort = iso => parseISO(iso).toLocaleDateString('ru-RU',{day:'numeric',month:'short'});
const weekday = iso => parseISO(iso).toLocaleDateString('ru-RU',{weekday:'long'});
const money = num => `${Math.round(Number(num)||0).toLocaleString('ru-RU')} ₽`;
const COLORS = ["orange","green","blue","purple","red"];
function seed(){const now=today(),old=shiftDate(now,-11),end=shiftDate(now,18),previous=addMonth(currentMonth(),-1);
 return {version:1,profile:{name:"Мой профиль",profession:"Машинист экскаватора",sector:"Строительство"},shift:{start:old,end},vacation:false,
 org:{name:"ООО «СеверСтрой»",description:"Строительство и обслуживание объектов",region:"Северный регион",ratings:{"Зарплата":4,"Бытовые условия":4,"Руководство":3,"График вахты":5},comment:"В целом устраивают условия работы. Есть нюансы с графиком, но коллектив хороший."},
 privacy:{status:"friends",countdown:"friends",calendar:"self",org:"friends",rating:"friends",comment:"self"},
 payments:[{id:id(),date:shiftDate(now,-2),type:"advance",amount:60000,description:"Демонстрационная запись"},{id:id(),date:`${previous}-20`,type:"salary",amount:68000,description:"Демонстрационная запись"}],
 notes:[{id:id(),title:"На следующую вахту",category:"Сборы",text:"",tasks:[{text:"Рабочая одежда",done:true},{text:"Термобельё",done:false},{text:"Документы",done:false},{text:"Зарядные устройства",done:false}],updated:now},{id:id(),title:"Идеи и планы",category:"Личное",text:"Не забыть про новые идеи для проекта.\nПозвонить домой в выходной.",tasks:[],updated:now}],
 friends:[{id:"f1",name:"Алексей Петров",role:"Бурильщик",company:"Северное бурение",state:"shift",days:12,letter:"А",skin:"alt1"},{id:"f2",name:"Иван Соколов",role:"Электромонтажник",company:"Строймонтаж",state:"rest",days:8,letter:"И",skin:"alt4"},{id:"f3",name:"Мария Соколова",role:"Геолог",company:"Георазведка",state:"vacation",days:5,letter:"М",skin:"alt2"},{id:"f4",name:"Сергей Кузнецов",role:"Механик",company:"Северная база",state:"shift",days:27,letter:"С",skin:"alt3"}],
 chats:[{id:"f1",name:"Алексей Петров",letter:"А",skin:"alt1",unread:2,messages:[{id:id(),out:false,text:"Привет! Как там на объекте?",time:"09:12"},{id:id(),out:false,text:"Всё нормально? Когда домой?",time:"09:24"}]},{id:"f2",name:"Иван Соколов",letter:"И",skin:"alt4",unread:1,messages:[{id:id(),out:false,text:"Увидимся на межвахте!",time:"Вчера"}]},{id:"f3",name:"Мария Соколова",letter:"М",skin:"alt2",unread:0,messages:[{id:id(),out:true,text:"Привет! Как отпуск?",time:"Вчера"},{id:id(),out:false,text:"Отлично, отдыхаю 😊",time:"Вчера"}]}],
 notifications:[{id:id(),title:"Вахта скоро закончится",body:"Осталось менее 3 недель до возвращения домой.",date:now,read:false,kind:"shift"},{id:id(),title:"Профессиональные праздники",body:"В календаре появились праздники разных профессий.",date:now,read:false,kind:"holiday"},{id:id(),title:"Новые сообщения",body:"В демонстрационных чатах есть непрочитанные сообщения.",date:now,read:false,kind:"message"}]
 };}
function load(){try{const x=JSON.parse(localStorage.getItem(STORAGE_KEY));if(!x||x.version!==1||!x.shift||!Array.isArray(x.payments)||!Array.isArray(x.notes)||!Array.isArray(x.chats))return seed();return x}catch{return seed()}}
let state=load();
const ui={view:"home",calendarMonth:currentMonth(),financeMonth:currentMonth(),selectedDate:today(),filter:"all",friendSearch:"",chatId:null,notificationOpen:false,holidaySector:"all",statsYear:new Date().getFullYear(),noteSearch:"",financeFilter:"all",friendFilter:"all",friendId:null};
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state))}catch{toast("Не удалось сохранить данные. Проверьте свободное место.")}}
function toast(message){const e=$('toast');e.textContent=message;e.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.hidden=true,3400)}
const button = (label,action,variant='secondary',attrs='') => `<button type="button" class="btn ${variant}" data-action="${action}" ${attrs}>${label}</button>`;
const title = (head,sub="",right="") => `<header class="page-title"><div><h1>${html(head)}</h1>${sub?`<p>${html(sub)}</p>`:''}</div>${right}</header>`;
const section=(head,act='',label='Все')=>`<div class="section-head"><h2>${html(head)}</h2>${act?`<button type="button" data-nav="${act}">${html(label)} ›</button>`:''}</div>`;
const tile=(symbol,color='')=>`<span class="icon-tile ${color}">${icon(symbol)}</span>`;
function status(){if(state.vacation)return {id:'vacation',label:'В отпуске',color:'purple'};if(today()>=state.shift.start&&today()<=state.shift.end)return {id:'shift',label:'На вахте',color:'green'};return {id:'rest',label:'На межвахте',color:'orange'}}
function inShift(day){return day>=state.shift.start&&day<=state.shift.end}
function shiftProgress(){const len=Math.max(1,daysBetween(state.shift.start,state.shift.end)+1);const elapsed=Math.min(len,Math.max(0,daysBetween(state.shift.start,today())+1));return {len,elapsed,percent:Math.round(elapsed/len*100),remaining:Math.max(0,daysBetween(today(),state.shift.end))}}
const STATUS_LABEL={shift:'На вахте',rest:'На межвахте',vacation:'В отпуске',offline:'Статус скрыт'};
function unreadMessages(){return state.chats.reduce((n,c)=>n+(Number(c.unread)||0),0)}
function unreadNotifications(){return state.notifications.filter(n=>!n.read).length}
function nav(view){ui.view=view;ui.chatId=view==='thread'?ui.chatId:null;render();$('appMain').scrollTop=0;window.location.hash=view==='home'?'':view}
function updateBadges(){const m=unreadMessages(),n=unreadNotifications();$('messagesBadge').hidden=m===0;$('messagesBadge').textContent=m>9?'9+':m;$('notificationBadge').hidden=n===0;$('notificationBadge').textContent=n>9?'9+':n;const selected=['thread','messages'].includes(ui.view)?'messages':ui.view==='friendProfile'?'friends':['organization','privacy','statistics','notes','holidays','profile','notifications','settings'].includes(ui.view)?'more':ui.view;document.querySelectorAll('.bottom-nav button').forEach(b=>{const a=b.dataset.nav===selected;b.classList.toggle('active',a);if(a)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')})}
function render(){updateBadges();const renderers={home:homePage,calendar:calendarPage,finance:financePage,messages:messagesPage,thread:threadPage,friends:friendsPage,friendProfile:friendProfilePage,more:morePage,organization:organizationPage,privacy:privacyPage,statistics:statsPage,notes:notesPage,holidays:holidaysPage,profile:profilePage,notifications:notificationsPage,settings:settingsPage};try{$('appMain').innerHTML=(renderers[ui.view]||homePage)()}catch(e){console.error('Render error',e);$('appMain').innerHTML='<div class="card"><h2>Не удалось открыть раздел</h2><p class="note-text">Попробуйте вернуться на главную страницу.</p>'+button('На главную','go-home','primary')+'</div>'}}
function nextEvents(){const p=state.payments.filter(p=>p.date>=today()).slice().sort((a,b)=>a.date.localeCompare(b.date)).map(p=>({date:p.date,title:p.type==='advance'?'Аванс':p.type==='salary'?'Зарплата':'Выплата',desc:money(p.amount),kind:'coins',color:'green'}));const events=[{date:state.shift.end,title:'Конец вахты',desc:'Возвращение на межвахтовый отдых',kind:'flag',color:'orange'}].concat(p).concat(holidaysForYear(parseISO(today()).getFullYear()).filter(h=>h.date>=today()).map(h=>({date:h.date,title:h.name,desc:h.sector,kind:'holiday',color:'red'}))).filter(x=>x.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4);return events}
function homePage(){const st=status(),p=shiftProgress();let heroText=st.id==='shift'?`${p.elapsed}-й день из ${p.len}`:st.id==='vacation'?'Отдых по вашему выбору':'Готовимся к новой вахте';const remaining=st.id==='shift'?`${p.remaining} ${plural(p.remaining,['день','дня','дней'])}`:st.id==='vacation'?'Время для себя':'Можно запланировать выезд';
return `<section class="hero-card"><div class="hero-photo"></div><div class="hero-body"><span class="hero-eyebrow">Текущий статус</span><div class="hero-status ${st.id}"><span class="status-dot"></span>${html(st.label)}</div><div class="hero-day">${html(heroText)}</div><div class="progress ${st.id==='shift'?'':'orange'}"><span style="--percent:${st.id==='shift'?p.percent:0}%"></span></div><div class="hero-meta"><div><span>Начало вахты</span><strong>${dateShort(state.shift.start)}</strong></div><div><span>Конец вахты</span><strong>${dateShort(state.shift.end)}</strong></div></div></div></section>
<div class="card countdown-card"><span class="countdown-icon">${icon('clock')}</span><div class="grow"><p class="small muted">${st.id==='shift'?'До межвахтового отдыха':st.id==='rest'?'Сейчас':'Ваш отдых'}</p><div class="countdown-large">${remaining}</div><p class="tiny muted">${st.id==='shift'?'Возвращение '+dateFull(state.shift.end):'Режим можно изменить вручную'}</p></div><button type="button" class="btn-round" data-action="edit-shift" aria-label="Настроить вахту">${icon('chevron')}</button></div>
<div class="card compact row between"><div class="row">${tile('eye','blue')}<div><strong class="small">Статус для друзей</strong><p class="tiny muted">${privacyName(state.privacy.status)} · отсчёт: ${privacyName(state.privacy.countdown)}</p></div></div><button class="btn small ghost" type="button" data-nav="privacy">Изменить ›</button></div>
${section('Быстрый доступ')}<div class="quick-grid">${[['calendar','calendar','Календарь','blue'],['finance','coins','Финансы','orange'],['notes','note','Заметки','purple'],['organization','building','Организация','purple'],['friends','friends','Друзья','green'],['statistics','chart','Статистика','green']].map(([v,i,l,c])=>`<button class="quick-card" type="button" data-nav="${v}"><span class="${c}">${icon(i)}</span><span>${l}</span></button>`).join('')}</div>
${section('Ближайшие события','calendar','Календарь')}
<div class="card compact">${nextEvents().length?nextEvents().map(ev=>`<div class="event-row"><div class="event-date"><strong>${parseISO(ev.date).getDate()}</strong><small>${parseISO(ev.date).toLocaleDateString('ru-RU',{month:'short'})}</small></div><div class="mini-circle ${ev.color}">${icon(ev.kind)}</div><div class="event-body"><strong>${html(ev.title)}</strong><p>${html(ev.desc)}</p></div></div>`).join(''):'<div class="empty">Пока нет событий. Отмечайте выплаты и планы в календаре.</div>'}</div>
<div class="offline-banner">${icon('shield')} Ваш календарь и финансы хранятся только на этом устройстве. Социальные функции пока демонстрационные.</div>`}
function plural(n,v){const a=Math.abs(n)%100,b=a%10;return a>10&&a<20?v[2]:b===1?v[0]:b>=2&&b<=4?v[1]:v[2]}
function privacyName(x){return ({all:'Всем',friends:'Друзьям',self:'Только мне'})[x]||'Только мне'}
function nthWeekday(year,month,weekDay,n){const first=new Date(year,month-1,1,12),offset=(weekDay-first.getDay()+7)%7;return localISO(new Date(year,month-1,1+offset+(n-1)*7,12))}
function lastWeekday(year,month,weekday){const last=new Date(year,month,0,12);return localISO(new Date(year,month-1,last.getDate()-(last.getDay()-weekday+7)%7,12))}
function holidaysForYear(year){return [
 {date:nthWeekday(year,4,0,1),name:'День геолога',sector:'Геология'},
 {date:nthWeekday(year,8,0,2),name:'День строителя',sector:'Строительство'},
 {date:lastWeekday(year,8,0),name:'День шахтёра',sector:'Горная промышленность'},
 {date:nthWeekday(year,9,0,1),name:'День работников нефтяной и газовой промышленности',sector:'Нефтегаз'},
 {date:lastWeekday(year,9,0),name:'День машиностроителя',sector:'Машиностроение'},
 {date:nthWeekday(year,10,0,3),name:'День работников дорожного хозяйства',sector:'Строительство'},
 {date:lastWeekday(year,10,0),name:'День автомобилиста',sector:'Транспорт'},
 {date:`${year}-12-22`,name:'День энергетика',sector:'Энергетика'},
 ].sort((a,b)=>a.date.localeCompare(b.date))}
const holidaysOn=date=>holidaysForYear(+date.slice(0,4)).filter(x=>x.date===date);
function calendarPage(){const [year,mon]=ui.calendarMonth.split('-').map(Number),first=new Date(year,mon-1,1,12),daysInMonth=new Date(year,mon,0,12).getDate(),pad=(first.getDay()+6)%7,count=Math.ceil((daysInMonth+pad)/7)*7;let grid='';for(let i=0;i<count;i++){const date=localISO(new Date(year,mon-1,1-pad+i,12)),d=parseISO(date),other=d.getMonth()!==mon-1,holiday=holidaysOn(date).length,pay=state.payments.some(p=>p.date===date),note=state.notes.some(n=>n.updated===date),type=state.vacation&&date===today()?'vacation':inShift(date)?'shift':'rest';grid+=`<button type="button" data-date="${date}" class="day ${other?'other':''} ${type} ${date===ui.selectedDate?'selected':''} ${date===today()?'today':''}" aria-label="${html(dateFull(date))}"><span class="number">${d.getDate()}</span><span class="dots">${holiday?'<i class="holiday"></i>':''}${pay?'<i class="pay"></i>':''}${note?'<i class="note"></i>':''}</span></button>`}
const d=ui.selectedDate;const pay=state.payments.filter(p=>p.date===d);const holiday=holidaysOn(d);return `${title('Календарь','Вахты, межвахта, выплаты и профессиональные праздники',`<button class="icon-button" data-action="add-payment" aria-label="Добавить запись">${icon('plus')}</button>`)}
<div class="card calendar-card"><div class="month-header"><button data-action="calendar-prev" aria-label="Предыдущий месяц">${icon('arrow-left')}</button><strong>${longMonth(ui.calendarMonth)}</strong><button data-action="calendar-next" aria-label="Следующий месяц">${icon('chevron')}</button></div><div class="calendar-grid">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<div class="weekday">${x}</div>`).join('')}${grid}</div><div class="calendar-legend"><span class="legend"><b style="background:#a7652a"></b>Вахта</span><span class="legend"><b style="background:#277b57"></b>Межвахта</span><span class="legend"><b style="background:#b884fb"></b>Отпуск</span><span class="legend"><b style="background:#f0c45c"></b>Выплата</span><span class="legend"><b style="background:#f2616b"></b>Праздник</span></div></div>
<div class="card calendar-day-detail"><div class="row between"><h3 class="calendar-detail-title">${html(dateFull(d))}</h3><button class="btn small ghost" data-action="add-note" data-prefill-date="${d}">${icon('plus')} Заметка</button></div><p class="tiny muted">${html(weekday(d))}</p><div class="detail-entry">${tile(inShift(d)?'helmet':'home',inShift(d)?'orange':'green')}<div class="grow"><strong>${inShift(d)?'Вахтовый день':'Межвахтовый отдых'}</strong><small>${inShift(d)?'День '+(daysBetween(state.shift.start,d)+1)+' по графику':'Вне диапазона текущей вахты'}</small></div></div>${pay.map(p=>`<div class="detail-entry">${tile('coins','green')}<div class="grow"><strong>${paymentType(p.type)} · ${money(p.amount)}</strong><small>${html(p.description||'Ручная запись')}</small></div></div>`).join('')}${holiday.map(h=>`<div class="detail-entry">${tile('holiday','red')}<div><strong>${html(h.name)}</strong><small>${html(h.sector)} · профессиональный праздник</small></div></div>`).join('')}<div class="calendar-actions">${button(icon('coins')+' Добавить выплату','add-payment','secondary',`data-prefill-date="${d}"`)}${button(icon('calendar')+' Вахта','edit-shift','secondary')}</div></div>
<div class="card compact row between"><div>${icon('eye')} <strong>Друзьям календарь</strong><p class="tiny muted">Сейчас: ${privacyName(state.privacy.calendar)}</p></div><button class="btn small ghost" data-nav="privacy">Настроить ›</button></div>${section('Профессиональные праздники','holidays','Все праздники')}`+holidayList(holidaysForYear(year).filter(x=>x.date.startsWith(ui.calendarMonth)).slice(0,5))}
function holidayList(items){return `<div class="card compact">${items.length?items.map(h=>`<div class="holiday-item"><div class="holiday-date">${parseISO(h.date).getDate()}<small>${parseISO(h.date).toLocaleDateString('ru-RU',{month:'short'})}</small></div>${tile('holiday','red')}<div><strong>${html(h.name)}</strong><p>${html(h.sector)}</p></div></div>`).join(''):'<div class="empty">В этом месяце праздников из справочника нет.</div>'}</div>`}
function paymentType(type){return ({advance:'Аванс',salary:'Зарплата',bonus:'Премия',other:'Другая выплата'})[type]||'Выплата'}
function paymentsInMonth(key){return state.payments.filter(p=>monthKey(p.date)===key).sort((a,b)=>b.date.localeCompare(a.date))}
function financePage(){const items=paymentsInMonth(ui.financeMonth),tot=items.reduce((sum,p)=>sum+(Number(p.amount)||0),0),advance=items.filter(p=>p.type==='advance').reduce((sum,p)=>sum+p.amount,0),salary=items.filter(p=>p.type==='salary').reduce((sum,p)=>sum+p.amount,0);const weeks=[0,0,0,0,0];items.forEach(p=>{const w=Math.min(4,Math.floor((parseISO(p.date).getDate()-1)/7));weeks[w]+=p.amount});const max=Math.max(1,...weeks);return `${title('Финансы','Ручной учёт авансов, зарплат и других выплат',`<button class="icon-button" data-action="add-payment" aria-label="Добавить выплату">${icon('plus')}</button>`)}<div class="card"><div class="month-header"><button data-action="finance-prev" aria-label="Предыдущий месяц">${icon('arrow-left')}</button><strong>${longMonth(ui.financeMonth)}</strong><button data-action="finance-next" aria-label="Следующий месяц">${icon('chevron')}</button></div><p class="small muted">Получено за месяц</p><div class="amount">${money(tot)}</div><p class="tiny muted">Записывайте фактические поступления, а не прогноз.</p><div class="chart-wrap"><div class="chart">${weeks.map((num,i)=>`<div class="chart-item" title="${money(num)}"><i style="--bar-height:${Math.round(num/max*83)}px"></i><span>${i+1} нед.</span></div>`).join('')}</div></div><div class="money-tiles"><div class="money-tile">${tile('coins','green')}<div class="amount-sm">${money(advance)}</div><p>Авансы</p></div><div class="money-tile">${tile('briefcase','purple')}<div class="amount-sm">${money(salary)}</div><p>Зарплаты</p></div></div>${button(icon('plus')+' Добавить выплату','add-payment','primary full')}</div>
${section('История выплат')}<div class="card compact">${items.length?items.map(p=>`<div class="payment-row">${tile(p.type==='advance'?'coins':'briefcase',p.type==='advance'?'green':'purple')}<div class="grow"><strong>${paymentType(p.type)}</strong><small>${dateFull(p.date)}${p.description?' · '+html(p.description):''}</small></div><div class="value">+ ${money(p.amount)}</div><button type="button" class="btn-round" data-action="edit-payment" data-id="${p.id}" aria-label="Изменить выплату">${icon('edit')}</button></div>`).join(''):'<div class="empty">Пока нет записей за этот месяц. Добавьте аванс или зарплату.</div>'}</div><div class="offline-banner">${icon('lock')} Финансовые записи — только для вас. Они не передаются друзьям даже при открытом календаре: показывается лишь факт выплаты, без суммы.</div>`}
function friendAvatar(f,size=""){
 const lookup={f1:"alexey",f2:"ivan",f3:"maria",f4:"sergey",f5:"alexey",f6:"ivan"};
 const key=lookup[f.id];
 if(key)return `<img class="friend-portrait ${size}" src="assets/avatar-${key}.svg" alt="" loading="lazy">`;
 return `<span class="avatar ${f.skin||"alt1"} ${size}">${html(f.letter||f.name[0])}</span>`;
}
function friendStatus(f){
 const config={
  shift:{label:"На вахте",detail:`Осталось ${f.days} ${plural(f.days,["день","дня","дней"])}`,color:"green",image:"shift"},
  rest:{label:"Межвахта",detail:`До вахты ${f.days} ${plural(f.days,["день","дня","дней"])}`,color:"orange",image:"rest"},
  vacation:{label:"Отпуск",detail:`Ещё ${f.days} ${plural(f.days,["день","дня","дней"])}`,color:"blue",image:"vacation"},
  offline:{label:"Не в сети",detail:"Статус не указан",color:"gray",image:"offline"}
 };
 const info=config[f.state]||config.offline;
 return `<span class="friend-status-panel"><span class="friend-status ${info.color}"><img src="assets/status-${info.image}.svg" alt="" aria-hidden="true"><span>${info.label}</span></span><small>${info.detail}</small></span>`;
}
function friendsPage(){
 const count=state.friends.length;
 const latest=state.chats.filter(ch=>ch.messages.length).slice(0,3);
 return `${title("Друзья","Коллеги, связь и планы",`<button class="icon-button" data-action="add-friend" aria-label="Добавить друга">${icon("plus")}</button>`)}
 <div class="friends-intro card compact"><span class="friend-group-icon">${icon("friends")}</span><div class="grow"><h3>Найдите коллег и друзей</h3><p>По имени, профессии или организации</p></div>${button("Добавить","add-friend","primary small")}</div>
 <div class="friend-tools"><label class="searchbox">${icon("search")}<input id="friendSearch" type="search" placeholder="Поиск друзей" value="${html(ui.friendSearch)}" aria-label="Поиск друзей"></label></div>
 <div class="section-head friends-heading"><h2>${icon("friends")} Мои друзья <span class="small muted">${count}</span></h2><select id="friendFilter" aria-label="Фильтр по статусу"><option value="all" ${ui.friendFilter==="all"?"selected":""}>Все статусы</option><option value="shift" ${ui.friendFilter==="shift"?"selected":""}>На вахте</option><option value="rest" ${ui.friendFilter==="rest"?"selected":""}>Межвахта</option><option value="vacation" ${ui.friendFilter==="vacation"?"selected":""}>Отпуск</option><option value="offline" ${ui.friendFilter==="offline"?"selected":""}>Не в сети</option></select></div>
 <div id="friendResults" class="card compact friend-list">${friendsMarkup()}</div>
 ${latest.length?`<div class="section-head recent-friend-heading"><h2>${icon("chat")} Последние сообщения</h2><button type="button" data-nav="messages">Все чаты ›</button></div><div class="card compact">${latest.map(ch=>{const m=ch.messages[ch.messages.length-1],f=state.friends.find(x=>x.id===ch.id)||ch;return `<button type="button" class="chat-row" data-action="open-chat" data-id="${html(ch.id)}">${friendAvatar(f)}<span class="grow"><strong class="friend-name">${html(ch.name)}</strong><small>${html(m?.text||"")}</small></span>${ch.unread?`<span class="list-count">${ch.unread}</span>`:icon("chevron")}</button>`}).join("")}</div>`:""}
 <p class="note-text friend-demo-notice">${icon("lock")} Пока это демонстрационные анкеты на вашем устройстве. Настоящие друзья и обмен статусами появятся после подключения сервера.</p>`;
}
function friendsMarkup(){
 const q=ui.friendSearch.trim().toLocaleLowerCase("ru");
 const list=state.friends.filter(f=>(ui.friendFilter==="all"||f.state===ui.friendFilter)&&[f.name,f.role,f.company].some(x=>String(x).toLocaleLowerCase("ru").includes(q)));
 return list.map(f=>`<button class="person-row friend-list-row" type="button" data-action="friend-detail" data-id="${html(f.id)}" aria-label="Открыть анкету: ${html(f.name)}">
 <span class="friend-picture">${friendAvatar(f)}<i class="friend-presence ${f.state==="offline"?"away":"available"}"></i></span>
 <span class="friend-bio"><strong class="friend-name">${html(f.name)}</strong><small>${html(f.company||"Компания не указана")} · ${html(f.role||"Профессия не указана")}</small></span>
 ${friendStatus(f)}<span class="friend-chevron">${icon("chevron")}</span></button>`).join("")||`<div class="empty">По выбранному фильтру друзей нет.</div>`;
}
function friendProfilePage(){
 const f=state.friends.find(x=>x.id===ui.friendId);
 if(!f)return `${title("Анкета друга")}${button("К списку друзей","back-to-friends","primary")}`;
 const demo={
 f1:{location:"ЯНАО, Новопортовское месторождение",schedule:"60/30",experience:"5 лет",about:"Работаю вахтовым методом. Люблю технику и надёжных людей.",rating:"4.6",review:"Хорошие условия на объекте, выплаты по графику."},
 f2:{location:"Тюменская область",schedule:"30/30",experience:"3 года",about:"Электромонтаж, работа на промышленных объектах.",rating:"4.2",review:"Команда отличная, условия нормальные."},
 f3:{location:"Красноярский край",schedule:"45/45",experience:"6 лет",about:"Исследую новые места и люблю путешествия.",rating:"4.4",review:"Интересные проекты и дружный коллектив."},
 f4:{location:"Республика Коми",schedule:"30/30",experience:"4 года",about:"Ремонт и обслуживание промышленного оборудования.",rating:"4.0",review:"Стабильная работа и понятные задачи."}
 }[f.id]||{location:"Не указано",schedule:"Не указан",experience:"Не указан",about:"Информация о себе пока не заполнена.",rating:null,review:""};
 const safeId=html(f.id);
 const isVisible=f.state!=="offline";
 return `<div class="friend-profile-header"><button type="button" class="friend-back" data-action="back-to-friends" aria-label="Назад к друзьям">${icon("arrow-left")}</button><h1>Профиль друга</h1><button type="button" class="friend-message-icon" data-action="chat-friend" data-id="${safeId}" aria-label="Написать другу">${icon("chat")}</button></div>
 <article class="card friend-profile-main"><div class="friend-profile-head">${friendAvatar(f,"profile-avatar-xl")}<div class="friend-profile-info"><h2>${html(f.name)}</h2><p>${html(f.company||"Организация не указана")}</p><p>${html(f.role||"Профессия не указана")}</p>${friendStatus(f)}</div></div></article>
 <article class="card friend-profile-section"><h3>${icon("friends")} О человеке</h3><p class="friend-about">${html(demo.about)}</p><dl class="friend-profile-facts"><div><dt>Организация</dt><dd>${html(f.company||"Не указана")}</dd></div><div><dt>Должность</dt><dd>${html(f.role||"Не указана")}</dd></div><div><dt>График</dt><dd>${html(demo.schedule)}</dd></div><div><dt>Регион</dt><dd>${html(demo.location)}</dd></div><div><dt>Стаж</dt><dd>${html(demo.experience)}</dd></div></dl></article>
 ${demo.rating?`<article class="card friend-profile-section"><div class="row between"><h3>${icon("star")} Организация</h3><span class="muted tiny">Демо-отзыв</span></div><div class="friend-rating"><b>${demo.rating}</b><span class="friend-starline">★★★★★</span></div><p class="friend-about">«${html(demo.review)}»</p></article>`:""}
 <article class="card friend-profile-section"><h3>${icon("calendar")} Текущий статус</h3><div class="friend-shift-card">${friendStatus(f)}${isVisible?`<div class="friend-shift-track"><span style="width:${Math.max(9,100-Math.min(90,Math.max(0,Number(f.days)||0)))}%"></span></div>`:""}</div>
 <div class="friend-sharing-note">${icon("shield")} Это демонстрационные данные. В реальном приложении календарь и отсчёт будут показаны только с разрешения друга.</div></article>
 <article class="card friend-profile-section"><h3>${icon("lock")} Конфиденциальность</h3><p class="friend-about">Анкета показывает только разрешённые владельцем сведения. Точные даты и календарь вахт могут быть скрыты.</p></article>
 <div class="friend-profile-actions">${button(`${icon("chat")} Написать`,"chat-friend","primary",`data-id="${safeId}"`)}${button(`${icon("arrow-left")} К друзьям`,"back-to-friends","secondary")}</div>
 <p class="note-text friend-demo-notice">Анкета демонстрационная. Рейтинг и биография здесь примерные и не относятся к реальным людям.</p>`;
}
function messagesPage(){const chats=state.chats;return `${title('Сообщения','Личные беседы и будущие групповые чаты',`<button class="icon-button" data-action="start-chat" aria-label="Новый чат">${icon('plus')}</button>`)}<div class="offline-banner">${icon('lock')} Сейчас это локальный демонстрационный чат. Сообщения не отправляются другим людям. В будущем здесь будет настоящая переписка.</div><div class="row between" style="margin:14px 0 6px"><h3>Все беседы</h3><span class="pill orange">${unreadMessages()} непрочитано</span></div><div class="card compact">${chats.length?chats.map(c=>{const m=c.messages[c.messages.length-1];return `<button class="chat-row" type="button" data-action="open-chat" data-id="${c.id}"><span class="avatar ${c.skin||'alt1'}">${html(c.letter||c.name[0])}</span><span class="grow"><strong class="friend-name">${html(c.name)}</strong><small>${m?html(m.text):'Начните диалог'}</small></span><span class="trailing"><time>${html(m?.time||'')}</time>${c.unread?`<span class="list-count">${c.unread}</span>`:''}</span></button>`}).join(''):'<div class="empty">Пока нет чатов. Выберите друга, чтобы начать переписку.</div>'}</div>`}
function threadPage(){const chat=state.chats.find(x=>x.id===ui.chatId);if(!chat)return `${title('Сообщения')}${button('К списку чатов','back-to-messages','secondary')}`;return `<header class="page-title" style="align-items:center"><div class="row"><button type="button" class="btn-round" data-action="back-to-messages" aria-label="Назад">${icon('arrow-left')}</button><span class="avatar ${chat.skin||'alt1'}" style="width:39px;height:39px">${html(chat.letter||chat.name[0])}</span><div><h1 style="font-size:17px;margin:0">${html(chat.name)}</h1><p>Локальный демочат</p></div></div></header><div class="offline-banner">Сообщения видны только на этом устройстве. Для отправки другому человеку потребуется сервер.</div><div class="chat-thread">${chat.messages.map(m=>`<div class="bubble ${m.out?'out':''}">${html(m.text)}<time>${html(m.time)}</time></div>`).join('')}</div><div class="composer"><input id="messageInput" type="text" maxlength="1000" autocomplete="off" placeholder="Написать сообщение…" aria-label="Написать сообщение"><button type="button" data-action="send-message" aria-label="Отправить сообщение">${icon('send')}</button></div>`}
function morePage(){return `${title('Ещё','Профиль, организация и личные инструменты')}<div class="card compact"><button class="more-item" data-nav="profile">${tile('friends','orange')}<span class="grow"><strong>Мой профиль</strong><small>Имя, профессия, статус</small></span>${icon('chevron','chev')}</button><button class="more-item" data-nav="organization">${tile('building','purple')}<span class="grow"><strong>Моя организация</strong><small>Рейтинг и отзыв работодателя</small></span>${icon('chevron','chev')}</button><button class="more-item" data-nav="privacy">${tile('lock','blue')}<span class="grow"><strong>Конфиденциальность</strong><small>Что видят друзья и другие люди</small></span>${icon('chevron','chev')}</button><button class="more-item" data-nav="notifications">${tile('bell','orange')}<span class="grow"><strong>Уведомления</strong><small>События и оповещения</small></span>${unreadNotifications()?`<span class="list-count">${unreadNotifications()}</span>`:''}${icon('chevron','chev')}</button></div><div class="card compact"><button class="more-item" data-nav="notes">${tile('note','orange')}<span class="grow"><strong>Мои заметки</strong><small>Записи и списки дел</small></span>${icon('chevron','chev')}</button><button class="more-item" data-nav="statistics">${tile('chart','green')}<span class="grow"><strong>Статистика</strong><small>Дни на вахте, выплаты и история</small></span>${icon('chevron','chev')}</button><button class="more-item" data-nav="holidays">${tile('holiday','red')}<span class="grow"><strong>Профессиональные праздники</strong><small>Календарь для разных профессий</small></span>${icon('chevron','chev')}</button><button class="more-item" data-nav="settings">${tile('settings','blue')}<span class="grow"><strong>Настройки и данные</strong><small>Резервная копия, импорт и режим работы</small></span>${icon('chevron','chev')}</button></div><p class="note-text">Версия 0.1 — HTML-прототип. Регистрация, настоящие друзья, переписка и синхронизация будут разработаны позже.</p>`}
function notesPage(){const list=state.notes.filter(n=>[n.title,n.category,n.text].join(' ').toLocaleLowerCase('ru').includes(ui.noteSearch.toLocaleLowerCase('ru')));return `${title('Заметки','Списки для сборов и личные записи',`<button class="icon-button" data-action="add-note" aria-label="Новая заметка">${icon('plus')}</button>`)}<label class="searchbox">${icon('search')}<input id="noteSearch" value="${html(ui.noteSearch)}" placeholder="Поиск по заметкам" aria-label="Поиск заметок"></label><div class="row" style="margin-bottom:15px">${button(icon('plus')+' Новая заметка','add-note','primary full')}${button(icon('backpack')+' Список дел','add-checklist','secondary full')}</div><div id="notesResults">${notesMarkup(list)}</div>`}
function notesMarkup(list){return list.map(n=>`<article class="card notes-card"><div class="row between"><div><strong>${html(n.title)}</strong><p class="tiny muted">${html(n.category)} · ${dateShort(n.updated)}</p></div><button class="btn-round" data-action="edit-note" data-id="${n.id}" aria-label="Изменить заметку">${icon('edit')}</button></div>${n.text?`<p class="notes-content">${html(n.text)}</p>`:''}${n.tasks.map((t,i)=>`<label class="task-item ${t.done?'completed':''}"><input type="checkbox" data-task-note="${n.id}" data-task-index="${i}" ${t.done?'checked':''}><span>${html(t.text)}</span></label>`).join('')}${!n.text&&!n.tasks.length?'<p class="note-text">Пустая заметка</p>':''}</article>`).join('')||'<div class="empty">Заметок пока нет.</div>'}
function ratingAverage(){const x=Object.values(state.org.ratings||{});return x.length?(x.reduce((a,b)=>a+Number(b),0)/x.length).toFixed(1):'0.0'}
function organizationPage(){return `${title('Организация','Личная оценка работодателя',`<button class="icon-button" data-action="edit-organization" aria-label="Изменить организацию">${icon('edit')}</button>`)}<article class="card"><div class="profile-cover"></div><div class="row between" style="align-items:start"><div><h2 class="company-title">${html(state.org.name)}</h2><p class="small muted">${html(state.org.description||'')}${state.org.region?' · '+html(state.org.region):''}</p></div></div></article><section class="card"><div class="row between"><h3>Моя оценка</h3><strong class="rating-average">★ ${ratingAverage()}</strong></div><p class="note-text" style="margin:8px 0">Нажимайте звёзды для изменения оценки.</p>${Object.entries(state.org.ratings).map(([label,value])=>`<div class="rating-row"><span>${html(label)}</span><div class="stars" aria-label="Оценка: ${value} из 5">${[1,2,3,4,5].map(v=>`<button type="button" class="${v<=value?'selected':''}" data-rating-label="${html(label)}" data-rating-value="${v}" aria-label="${v} из 5" title="${v} из 5">${icon('star')}</button>`).join('')}</div></div>`).join('')}</section><article class="card"><div class="card-title"><span>Мой комментарий</span><button class="btn small ghost" data-action="edit-comment">${icon('edit')} Изменить</button></div><p class="notes-content">${html(state.org.comment||'Вы ещё не оставили комментарий.')}</p></article><article class="card"><div class="card-title">${icon('eye')} Кому это видно</div>${privacyMini('org','Название организации')}${privacyMini('rating','Моя оценка')}${privacyMini('comment','Мой отзыв')}</article><div class="offline-banner">Отзывы здесь пока личные и не публикуются в общей базе работодателей. Синхронизацию и модерацию добавим с серверной частью.</div>`}
function privacyMini(key,label){return `<div class="privacy-row"><div><strong>${html(label)}</strong></div><button class="btn small secondary" data-nav="privacy">${privacyName(state.privacy[key])} ›</button></div>`}
const privacyFields=[['status','Статус','Вахта, межвахта или отпуск'],['countdown','Обратный отсчёт','Через сколько дней домой'],['calendar','Календарь вахт','Рабочие и свободные даты'],['org','Моя организация','Название работодателя'],['rating','Оценка организации','Рейтинг по критериям'],['comment','Комментарий','Ваш личный отзыв']];
function privacyPage(){return `${title('Конфиденциальность','Вы решаете, что смогут увидеть другие')}<div class="card"><div class="card-title">${icon('shield')} Видимость данных</div>${privacyFields.map(([key,label,desc])=>`<label class="privacy-row"><div><strong>${html(label)}</strong><small>${html(desc)}</small></div><select data-privacy="${key}" aria-label="${html(label)}"><option value="all" ${state.privacy[key]==='all'?'selected':''}>Всем</option><option value="friends" ${state.privacy[key]==='friends'?'selected':''}>Друзьям</option><option value="self" ${state.privacy[key]==='self'?'selected':''}>Только мне</option></select></label>`).join('')}<div class="privacy-row locked">${tile('lock','blue')}<div><strong>Суммы выплат</strong><small>Всегда скрыты от других</small></div><span>Только мне</span></div></div><div class="card"><div class="card-title">${icon('eye')} Предпросмотр для друга</div>${previewForFriend()}</div><p class="note-text">В этой версии настройки сохраняются локально. На сервере эти ограничения обязательно будут проверяться независимо от интерфейса.</p>`}
function previewForFriend(){const can = k=>['all','friends'].includes(state.privacy[k]);const st=status(),p=shiftProgress();return `<p class="note-text">Друг увидит примерно такую карточку:</p><div class="card compact" style="margin-top:10px"><strong>${html(state.profile.name)}</strong><div style="margin-top:7px">${can('status')?`<span class="pill ${st.color}">${st.label}</span>`:'<span class="pill gray">Статус скрыт</span>'}</div>${can('countdown')?`<p class="small muted" style="margin-top:8px">${st.id==='shift'?'Домой через '+p.remaining+' дней':'На отдыхе'}</p>`:''}${can('org')?`<p class="small muted" style="margin-top:7px">Работает в ${html(state.org.name)}</p>`:''}${can('rating')?`<p class="small muted" style="margin-top:7px">Оценка: ★ ${ratingAverage()}</p>`:''}${can('comment')?`<p class="tiny muted" style="margin-top:7px">«${html(state.org.comment)}»</p>`:''}<div class="tiny muted" style="margin-top:10px">Календарь: ${can('calendar')?'доступен':'скрыт'} · Суммы выплат: скрыты</div></div>`}
function profilePage(){const st=status();return `${title('Мой профиль','Информация, которая относится к вам',`<button class="icon-button" data-action="edit-profile" aria-label="Изменить профиль">${icon('edit')}</button>`)}<div class="card"><div class="row"><span class="avatar alt1" style="width:62px;height:62px;font-size:23px">${html(state.profile.name.slice(0,1).toUpperCase())}</span><div><h2>${html(state.profile.name)}</h2><p class="small muted" style="margin-top:5px">${html(state.profile.profession)}</p><span class="pill ${st.color}" style="margin-top:8px">${st.label}</span></div></div></div><div class="card"><div class="card-title">${icon('calendar')} Мой график</div><p class="small muted">Начало: ${dateFull(state.shift.start)}</p><p class="small muted" style="margin-top:6px">Конец: ${dateFull(state.shift.end)}</p><div style="margin-top:12px">${button('Изменить даты вахты','edit-shift','primary full')}</div><div style="margin-top:9px">${button('Статус: '+(state.vacation?'отпуск':'автоматически'),'edit-status','secondary full')}</div></div><div class="card"><div class="card-title">${icon('eye')} Настройки видимости</div><p class="note-text">Статус: ${privacyName(state.privacy.status)}. Календарь: ${privacyName(state.privacy.calendar)}.</p><div style="margin-top:12px">${button('Управление конфиденциальностью','go-privacy','secondary full')}</div></div>`}
function statsPage(){const year=ui.statsYear;let days=0;let months=[],amount=0;for(let m=1;m<=12;m++){let count=0;const max=new Date(year,m,0).getDate();for(let d=1;d<=max;d++){const iso=`${year}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`;if(inShift(iso))count++}days+=count;months.push(count)}const pays=state.payments.filter(p=>p.date.startsWith(String(year)));amount=pays.reduce((s,p)=>s+p.amount,0);const mx=Math.max(...months,1);return `${title('Статистика','Рабочее время и история за выбранный год')}<div class="card"><div class="month-header"><button data-action="stats-prev">${icon('arrow-left')}</button><strong>${year} год</strong><button data-action="stats-next">${icon('chevron')}</button></div><div class="stat-grid"><div class="money-tile">${tile('helmet','orange')}<div class="stat-number">${days}</div><div class="stat-label">Дней на вахте</div></div><div class="money-tile">${tile('home','green')}<div class="stat-number">${Math.max(0,daysInYear(year)-days)}</div><div class="stat-label">Дней вне этой вахты</div></div><div class="money-tile">${tile('coins','green')}<div class="stat-number" style="font-size:18px">${money(amount)}</div><div class="stat-label">Записано выплат</div></div><div class="money-tile">${tile('calendar','blue')}<div class="stat-number">${pays.length}</div><div class="stat-label">Финансовых записей</div></div></div></div><div class="card"><div class="card-title">Дни по текущему графику</div><div class="chart-wrap"><div class="chart">${months.map((n,i)=>`<div class="chart-item"><i style="--bar-height:${Math.round(n/mx*84)}px;background:linear-gradient(180deg,#ffb36e,#de6822)"></i><span>${['Я','Ф','М','А','М','И','И','А','С','О','Н','Д'][i]}</span></div>`).join('')}</div></div><p class="note-text" style="margin-top:14px">Это статистика по указанному диапазону одной вахты. Для полной годовой истории позже добавим сохранение нескольких вахт.</p></div>${button('Перейти к выплатам','go-finance','primary full')}`}
function daysInYear(y){return (new Date(y+1,0,1)-new Date(y,0,1))/86400000}
function holidaysPage(){const yr=parseISO(today()).getFullYear(), all=[...holidaysForYear(yr),...holidaysForYear(yr+1)];const sectors=['all',...new Set(all.map(x=>x.sector))];const selected=all.filter(h=>ui.holidaySector==='all'||ui.holidaySector===h.sector);return `${title('Профессиональные праздники','Справочник дат для разных рабочих специальностей')}<label class="field"><span>Фильтр по сфере работы</span><select id="holidayFilter">${sectors.map(s=>`<option value="${html(s)}" ${s===ui.holidaySector?'selected':''}>${s==='all'?'Все профессии':html(s)}</option>`).join('')}</select></label>${holidayList(selected)}<p class="note-text">Показаны наиболее известные профессиональные праздники. Даты переходящих праздников рассчитываются для каждого года. Это справочный список, его будем расширять.</p>`}
function notificationsPage(){return `${title('Уведомления','Новости по вашему графику и приложению',button('Прочитать все','read-all','secondary small'))}<div class="card compact">${state.notifications.length?state.notifications.map(n=>`<button type="button" class="chat-row" data-action="read-notification" data-id="${n.id}">${tile(n.kind==='message'?'chat':n.kind==='holiday'?'holiday':'bell',n.read?'blue':'orange')}<div class="grow"><strong class="friend-name">${html(n.title)}</strong><small style="white-space:normal">${html(n.body)}</small><small>${dateShort(n.date)}</small></div>${!n.read?'<span class="list-count">1</span>':''}</button>`).join(''):'<div class="empty">Пока уведомлений нет.</div>'}</div>`}
function settingsPage(){return `${title('Настройки и данные','Приложение без обязательной регистрации')}<div class="card"><div class="card-title">${icon('shield')} Локальные данные</div><p class="note-text">Вахта, выплаты и заметки хранятся в памяти этого браузера. Чтобы перенести их на другой телефон, сохраните резервную копию.</p><div class="row" style="margin-top:13px">${button(icon('download')+' Экспорт JSON','export','primary full')}${button(icon('upload')+' Импорт','import','secondary full')}</div></div><div class="card"><div class="card-title">Демонстрационные данные</div><p class="note-text">Образцы чатов и друзей показывают будущий интерфейс социальной части. Реальная переписка пока недоступна.</p><div style="margin-top:14px">${button('Сбросить прототип','reset','danger full')}</div></div><div class="card"><div class="card-title">Версия 0.1.0 · HTML-прототип</div><p class="note-text">Без сервера, без облачного профиля и без отправки данных другим людям. Готов для проверки дизайна на GitHub Pages и смартфонах.</p></div>`}
let onModalSave=null;
let editingPayment=null;
function openDialog(heading,body,onSave=null,saveLabel='Сохранить',additional=''){
 onModalSave=onSave;const dialog=$('appDialog');$('dialogTitle').textContent=heading;$('dialogBody').innerHTML=body;$('dialogActions').innerHTML=additional+`<button class="btn secondary" type="button" data-action="close-dialog">Отмена</button>`+(onSave?`<button class="btn primary" type="submit">${html(saveLabel)}</button>`:'');
 if(!dialog.open)dialog.showModal();
}
function closeDialog(){$('appDialog').close();onModalSave=null;editingPayment=null}
const inputField=(label,name,value,type='text',extra='')=>`<label class="field"><span>${html(label)}</span><input name="${name}" type="${type}" value="${html(value)}" ${extra}></label>`;
const selectField=(label,name,values,value)=>`<label class="field"><span>${html(label)}</span><select name="${name}">${values.map(([v,text])=>`<option value="${html(v)}" ${v===value?'selected':''}>${html(text)}</option>`).join('')}</select></label>`;
const textareaField=(label,name,value,placeholder='')=>`<label class="field"><span>${html(label)}</span><textarea name="${name}" placeholder="${html(placeholder)}">${html(value)}</textarea></label>`;
function editShift(){openDialog('Даты вахты',`<p class="note-text" style="margin-bottom:13px">По этим датам автоматически определяются статус, отсчёт отработанных дней и календарь.</p>${inputField('Начало вахты','start',state.shift.start,'date','required')}${inputField('Конец вахты','end',state.shift.end,'date','required')}`,form=>{const start=form.get('start'),end=form.get('end');if(!/^\d{4}-\d{2}-\d{2}$/.test(start)||!/^\d{4}-\d{2}-\d{2}$/.test(end)||start>end){toast('Проверьте даты: конец должен быть не раньше начала.');return false}state.shift={start,end};ui.selectedDate=start;ui.calendarMonth=monthKey(start);persist();toast('График вахты сохранён');return true})}
function editStatus(){openDialog('Статус',`<p class="note-text" style="margin-bottom:15px">«На вахте» и «На межвахте» рассчитываются автоматически. Отпуск можно включить вручную.</p>${selectField('Режим статуса','status',[['auto','Автоматически по датам'],['vacation','Отпуск (вручную)']],state.vacation?'vacation':'auto')}`,form=>{state.vacation=form.get('status')==='vacation';persist();toast('Статус обновлён');return true})}
function paymentDialog(existing=null,date=today()){
 editingPayment=existing?.id||null;
 openDialog(existing?'Изменить выплату':'Добавить выплату',`${selectField('Вид выплаты','type',[['advance','Аванс'],['salary','Зарплата'],['bonus','Премия'],['other','Другая выплата']],existing?.type||'advance')}${inputField('Сумма в рублях','amount',existing?.amount||'','number','required min="1" step="1" placeholder="Например, 60000"')}${inputField('Дата поступления','date',existing?.date||date,'date','required')}${textareaField('Комментарий (необязательно)','description',existing?.description||'','За какой период получено')}`,form=>{
 const type=form.get('type'),date=form.get('date'),amount=Number(form.get('amount')),description=String(form.get('description')||'').trim().slice(0,300);
 if(!['advance','salary','bonus','other'].includes(type)||!Number.isSafeInteger(amount)||amount<=0||amount>1000000000||!/^\d{4}-\d{2}-\d{2}$/.test(date)){toast('Укажите корректную дату и сумму в рублях.');return false}
 if(existing){existing.type=type;existing.date=date;existing.amount=amount;existing.description=description}else state.payments.push({id:id(),type,date,amount,description});
 ui.financeMonth=monthKey(date);persist();toast(existing?'Выплата обновлена':'Выплата добавлена');return true
 },'Сохранить',existing?`<button class="btn danger" type="button" data-action="delete-payment" data-id="${existing.id}">Удалить</button>`:'')
}
function noteDialog(existing=null,type='note',date=today()){
 const isChecklist=type==='checklist'||(existing&&existing.tasks.length>0);
 const category=existing?.category||(isChecklist?'Сборы':'Личное');
 openDialog(existing?'Изменить заметку':isChecklist?'Новый список дел':'Новая заметка',`${inputField('Название','title',existing?.title||'','text','maxlength="100" required')}${selectField('Категория','category',[['Сборы','Сборы'],['Работа','Работа'],['Личное','Личное'],['Идеи','Идеи']],category)}${textareaField('Текст заметки','text',existing?.text||'','Короткая запись, мысль или напоминание')}${textareaField('Пункты списка — каждый с новой строки','tasks',existing?.tasks.map(x=>x.text).join('\n')||'','Документы\nЗарядка\nСредства защиты')}`,form=>{
 const title=String(form.get('title')||'').trim(),text=String(form.get('text')||'').slice(0,5000),category=String(form.get('category')||'Личное'),raw=String(form.get('tasks')||'');
 if(!title){toast('Введите название заметки.');return false}
 const previous=existing?.tasks||[];
 const tasks=raw.split(/\r?\n/).map(x=>x.trim()).filter(Boolean).slice(0,70).map((text,i)=>({text:text.slice(0,200),done:previous[i]?.text===text?Boolean(previous[i].done):false}));
 if(existing){Object.assign(existing,{title:title.slice(0,100),text,category,tasks,updated:date})}else state.notes.unshift({id:id(),title:title.slice(0,100),text,category,tasks,updated:date});
 persist();toast('Заметка сохранена');return true
 },'Сохранить',existing?`<button class="btn danger" type="button" data-action="delete-note" data-id="${existing.id}">Удалить</button>`:'')
}
function editProfile(){openDialog('Мой профиль',`${inputField('Имя или псевдоним','name',state.profile.name,'text','required maxlength="70"')}${inputField('Профессия','profession',state.profile.profession,'text','maxlength="90"')}${selectField('Сфера работы','sector',[['Строительство','Строительство'],['Нефтегаз','Нефтегаз'],['Горная промышленность','Горная промышленность'],['Транспорт','Транспорт'],['Энергетика','Энергетика'],['Геология','Геология'],['Машиностроение','Машиностроение'],['Другое','Другое']],state.profile.sector)}`,form=>{const name=String(form.get('name')||'').trim();if(!name){toast('Укажите имя или псевдоним.');return false}state.profile.name=name.slice(0,70);state.profile.profession=String(form.get('profession')||'').slice(0,90);state.profile.sector=String(form.get('sector')||'Другое');persist();return true})}
function editOrganization(){openDialog('Моя организация',`${inputField('Название организации','name',state.org.name,'text','required maxlength="140"')}${inputField('Род деятельности','description',state.org.description,'text','maxlength="200"')}${inputField('Регион / объект','region',state.org.region,'text','maxlength="140"')}`,form=>{const name=String(form.get('name')||'').trim();if(!name){toast('Укажите организацию.');return false}state.org.name=name.slice(0,140);state.org.description=String(form.get('description')||'').slice(0,200);state.org.region=String(form.get('region')||'').slice(0,140);persist();return true})}
function editComment(){openDialog('Мой отзыв',`<p class="note-text" style="margin-bottom:11px">Личный отзыв работодателю. Публикации и модерации в прототипе ещё нет.</p>${textareaField('Комментарий','comment',state.org.comment,'Что нравится? Что можно улучшить?')}`,form=>{state.org.comment=String(form.get('comment')||'').trim().slice(0,1000);persist();toast('Отзыв обновлён');return true})}
function addFriend(){openDialog('Добавить друга',`<div class="offline-banner">Это локальный пример профиля друга, а не реальный запрос дружбы.</div>${inputField('Имя','name','','text','required maxlength="80"')}${inputField('Профессия','role','','text','maxlength="80"')}${inputField('Организация','company','','text','maxlength="80"')}`,form=>{const name=String(form.get('name')||'').trim();if(!name){toast('Введите имя.');return false}state.friends.push({id:id(),name:name.slice(0,80),letter:name[0].toUpperCase(),role:String(form.get('role')||'').slice(0,80),company:String(form.get('company')||'').slice(0,80),state:'offline',days:0,skin:'alt3'});persist();toast('Демо-профиль добавлен');return true},'Добавить')}
function friendDetail(friendId){if(!state.friends.some(x=>x.id===friendId))return;ui.friendId=friendId;nav("friendProfile")}
function startChat(){if(!state.friends.length){toast('Сначала добавьте демо-друга.');return}openDialog('Новый разговор',`<p class="note-text" style="margin-bottom:12px">Выберите человека, чтобы открыть локальный демочат.</p>${selectField('Друг','friendId',state.friends.map(f=>[f.id,f.name]),state.friends[0].id)}`,form=>{const f=state.friends.find(x=>x.id===form.get('friendId'));if(!f)return false;setTimeout(()=>openChat(f.id),0);return true},'Открыть чат')}
function openChat(friendId){const friend=state.friends.find(f=>f.id===friendId);let chat=state.chats.find(c=>c.id===friendId);if(!chat){if(!friend){toast('Друг не найден.');return}chat={id:friend.id,name:friend.name,letter:friend.letter,skin:friend.skin,unread:0,messages:[]};state.chats.unshift(chat)}chat.unread=0;persist();ui.chatId=chat.id;nav('thread')}
function sendMessage(){const input=$('messageInput');if(!input)return;const value=input.value.trim();if(!value)return;const chat=state.chats.find(c=>c.id===ui.chatId);if(!chat)return;chat.messages.push({id:id(),out:true,text:value.slice(0,1000),time:new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})});persist();render();$('appMain').scrollTop=$('appMain').scrollHeight;toast('Сохранено только в этом браузере')}
function dataExport(){const blob=new Blob([JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2)],{type:'application/json;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`moya-vahta-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);toast('Резервная копия сохранена')}
function validateBackup(x){if(!x||x.version!==1||typeof x.profile?.name!=='string'||typeof x.shift?.start!=='string'||typeof x.shift?.end!=='string'||!Array.isArray(x.payments)||!Array.isArray(x.notes)||!Array.isArray(x.friends)||!Array.isArray(x.chats)||!Array.isArray(x.notifications)||!x.privacy||!x.org)throw Error('Некорректный формат резервной копии');if(x.payments.length>20000||x.notes.length>5000||x.friends.length>5000||x.chats.length>2000)throw Error('Слишком большой архив');if(!/^\d{4}-\d{2}-\d{2}$/.test(x.shift.start)||!/^\d{4}-\d{2}-\d{2}$/.test(x.shift.end)||x.shift.start>x.shift.end)throw Error('Неверные даты вахты');return x}
function handleAction(action,el){switch(action){
case 'close-dialog':closeDialog();return;
case 'go-home':nav('home');return;
case 'go-finance':nav('finance');return;
case 'go-privacy':nav('privacy');return;
case 'open-notifications':nav('notifications');return;
case 'calendar-prev':case 'calendar-next':ui.calendarMonth=addMonth(ui.calendarMonth,action==='calendar-prev'?-1:1);ui.selectedDate=ui.calendarMonth+'-01';render();return;
case 'finance-prev':case 'finance-next':ui.financeMonth=addMonth(ui.financeMonth,action==='finance-prev'?-1:1);render();return;
case 'stats-prev':case 'stats-next':ui.statsYear+=action==='stats-prev'?-1:1;render();return;
case 'edit-shift':editShift();return;
case 'edit-status':editStatus();return;
case 'add-payment':paymentDialog(null,el.dataset.prefillDate||today());return;
case 'edit-payment':paymentDialog(state.payments.find(p=>p.id===el.dataset.id));return;
case 'delete-payment':if(confirm('Удалить запись о выплате?')){state.payments=state.payments.filter(p=>p.id!==el.dataset.id);closeDialog();persist();render();toast('Выплата удалена')}return;
case 'add-note':noteDialog(null,'note',el.dataset.prefillDate||today());return;
case 'add-checklist':noteDialog(null,'checklist');return;
case 'edit-note':noteDialog(state.notes.find(n=>n.id===el.dataset.id));return;
case 'delete-note':if(confirm('Удалить заметку?')){state.notes=state.notes.filter(n=>n.id!==el.dataset.id);closeDialog();persist();render();toast('Заметка удалена')}return;
case 'edit-profile':editProfile();return;
case 'edit-organization':editOrganization();return;
case 'edit-comment':editComment();return;
case 'add-friend':addFriend();return;
case 'friend-detail':friendDetail(el.dataset.id);return;
case 'back-to-friends':nav('friends');return;
case 'chat-friend':{const fid=el.dataset.id;if($('appDialog').open)closeDialog();openChat(fid);return}
case 'start-chat':startChat();return;
case 'open-chat':openChat(el.dataset.id);return;
case 'back-to-messages':nav('messages');return;
case 'send-message':sendMessage();return;
case 'read-all':state.notifications.forEach(n=>n.read=true);persist();render();return;
case 'read-notification':{const n=state.notifications.find(x=>x.id===el.dataset.id);if(n)n.read=true;persist();render();return}
case 'export':dataExport();return;
case 'import':$('importFile').click();return;
case 'reset':if(confirm('Сбросить все локальные данные, включая выплаты и заметки? Сделайте резервную копию перед удалением.')){state=seed();persist();ui.view='home';render();toast('Прототип сброшен')}return;
}}
document.addEventListener('click',event=>{const el=event.target.closest('button,[data-date]');if(!el)return;const action=el.dataset.action;if(action){handleAction(action,el);return}if(el.dataset.nav){nav(el.dataset.nav);return}if(el.dataset.date){ui.selectedDate=el.dataset.date;render();return}if(el.dataset.ratingLabel){const key=el.dataset.ratingLabel,val=Number(el.dataset.ratingValue);if(Object.hasOwn(state.org.ratings,key)&&val>=1&&val<=5){state.org.ratings[key]=val;persist();render()}return}});
// Rating stars and date cells are buttons and are handled in one delegated click listener.
document.addEventListener('change',event=>{const t=event.target;if(t.dataset.privacy){const val=t.value;if(['all','friends','self'].includes(val)){state.privacy[t.dataset.privacy]=val;persist();render();toast('Настройки видимости сохранены')}return}if(t.dataset.taskNote){const note=state.notes.find(n=>n.id===t.dataset.taskNote),task=note?.tasks[Number(t.dataset.taskIndex)];if(task){task.done=t.checked;persist();const l=t.closest('.task-item');l?.classList.toggle('completed',t.checked)}return}if(t.id==='holidayFilter'){ui.holidaySector=t.value;render();return}if(t.id==='friendFilter'){ui.friendFilter=t.value;$('friendResults').innerHTML=friendsMarkup();return}});
document.addEventListener('input',event=>{const t=event.target;if(t.id==='friendSearch'){ui.friendSearch=t.value;$('friendResults').innerHTML=friendsMarkup()}if(t.id==='noteSearch'){ui.noteSearch=t.value;const list=state.notes.filter(n=>[n.title,n.category,n.text].join(' ').toLocaleLowerCase('ru').includes(ui.noteSearch.toLocaleLowerCase('ru')));$('notesResults').innerHTML=notesMarkup(list)}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='messageInput'){e.preventDefault();sendMessage()}});
$('dialogForm').addEventListener('submit',e=>{e.preventDefault();if(!onModalSave)return;const callback=onModalSave,success=callback(new FormData(e.currentTarget));if(success!==false){closeDialog();render()}});
$('importFile').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;if(file.size>3*1024*1024){toast('Файл больше 3 МБ.');return}try{const incoming=validateBackup(JSON.parse(await file.text()));if(!confirm('Импорт заменит все локальные данные. Продолжить?'))return;state=incoming;persist();nav('home');toast('Данные восстановлены')}catch(err){toast('Ошибка импорта: '+err.message)}});
$('appDialog').addEventListener('click',e=>{if(e.target===$('appDialog'))closeDialog()});
window.addEventListener('focus',()=>{render()});
// Use hash navigation only for known top-level views. Never interpolate it into HTML.
const hash=location.hash.replace(/^#/, '');if(['home','calendar','finance','messages','friends','more','organization','privacy','statistics','notes','holidays','profile','notifications','settings'].includes(hash))ui.view=hash;
render();
})();
